package io.github.diodeme.ji.security.secret;

import java.util.Optional;

/** Host-only credential persistence. Implementations never return material to transport DTOs. */
public interface CredentialStore extends AutoCloseable {
    long put(String credentialId, SecretValue secret, long expectedRevision);

    Optional<ResolvedCredential> resolve(String credentialId);

    long delete(String credentialId, long expectedRevision);

    int rotateToActiveKey();

    @Override
    default void close() {
    }

    record ResolvedCredential(String credentialId, long revision, SecretValue secret) implements AutoCloseable {
        public ResolvedCredential {
            if (credentialId == null || credentialId.isBlank()) throw new IllegalArgumentException("credentialId must not be blank");
            if (revision < 1) throw new IllegalArgumentException("revision must be positive");
            if (secret == null) throw new IllegalArgumentException("secret is required");
        }

        @Override
        public void close() {
            secret.close();
        }

        @Override
        public String toString() {
            return "ResolvedCredential[credentialId=" + credentialId + ", revision=" + revision + ", secret=REDACTED]";
        }
    }
}
